def find_second_largest(numbers):
    if len(numbers) < 2:
        return "リストは2つ以上の要素が必要です"

    max_num = numbers[0]
    second_max = numbers[0]

    for num in numbers[1:]:
        if num > max_num:
            second_max = max_num
            max_num = num
        elif num > second_max and num != max_num:
            second_max = num

    if second_max == max_num:
        return None
    else:
        return second_max

